```javascript
function reverseAdjectives(sentence) {
  const parts = sentence.split(/[ \t\n\r]+/); // split into an array by any whitespace character
  const adjectives = [];
  let lastNonAdjunct = -1;
  for (let I = 0; I < parts.length; i++) {
    const part = parts[i];
    if (part.match(/^\p{L}+$/) && !part.match(/^[\w']+$/) && I > lastNonAdjunct) { // check if it's an adjective and not a noun or proper noun
      lastNonAdjunct = i;
    }
    if (lastNonAdjunct >= 0 && part.match(/^[\w']+$/) && I > lastNonAdjunct) { // check if it's a noun or proper noun after the last adjective
      adjectives.push(parts.slice(lastNonAdjunct + 1, i).join(" ") + " ");
      parts.splice(lastNonAdjunct + 1, i - lastNonAdjunct, ""); // remove the space between the last adjective and the current noun or proper noun
    }
    if (part.match(/^\p{L}+$/) && !part.match(/^[\w']+$/)) { // check if it's an adjective again
      adjectives.push(part);
      lastNonAdjunct = -1;
    }
  }
  return adjectives.reverse().join(" ") + " " + parts.filter((x) => x.trim()).join(" "); // join the reversed adjectives with a space, then join the rest of the sentence with spaces
}

console.log(reverseAdjectives("Beautiful green trees are in the park.")); // Output: "Green beautiful trees are in the park."
```

