function determineRelevantProtocol(inputData) {
  let relevanceA = 0;
  let relevanceB = 0;
  let relevanceC = 0;

  // Check for IPv6
  if (inputData.sourceIP && inputData.sourceIP.includes("::") || inputData.destinationIP && inputData.destinationIP.includes("::")) {
    relevanceA += 100;
  }

  // Check for HTTP
  if (inputData.port === 80 || inputData.port === 443) {
    relevanceB += 100;
  }

  // Check for UDP
  relevanceC += 9;

  // Return the highest relevance score
  return Math.max(relevanceA, relevanceB, relevanceC);
}
```

